/*
 * Copyright (c) 2026 Advanced Micro Devices, Inc.
 * SPDX-License-Identifier: MIT
 *
 * Linker version script defining the complete exported ABI of librocjitsu.so.
 * Every symbol not listed under `global` is given local (hidden) binding, so
 * the dynamic symbol table stays limited to the intended surface.
 *
 * This complements the project-wide hidden visibility (CMAKE_CXX_VISIBILITY_PRESET
 * hidden). Visibility alone cannot make the surface fully pristine because:
 *   - the interposer wraps its libc overrides in `#pragma GCC visibility
 *     push(default)`, which also promotes the std:: template instantiations,
 *     typeinfos and vtables generated inside that region, and
 *   - libstdc++ marks `namespace std` as _GLIBCXX_VISIBILITY(default), so some
 *     std:: typeinfos stay default-visible even under -fvisibility=hidden.
 * The `local: *` rule below overrides ELF visibility at link time and drops all
 * of that, leaving only the two intended groups.
 *
 * Public groups:
 *   1. The rj_* C API (rj_vm_*, rj_code_*, rj_kfd_*), marked RJ_API_EXPORT.
 *   2. The libc functions interposed by the LD_PRELOAD shim in
 *      lib/rocjitsu/src/rocjitsu/kmd/linux/interposer.cpp. These MUST remain
 *      exported so the preload can intercept the amdgpu/KFD syscall surface.
 *      When adding or removing an interposed libc function, update this list.
 */
{
  global:
    rj_*;

    access;
    close;
    dup;
    dup2;
    dup3;
    fcntl;
    fcntl64;
    fopen;
    fopen64;
    fork;
    freopen;
    freopen64;
    fstat;
    fstat64;
    __fxstat;
    __fxstat64;
    ioctl;
    lstat;
    lstat64;
    __lxstat;
    __lxstat64;
    madvise;
    mmap;
    mprotect;
    munmap;
    open;
    open64;
    __open_2;
    __open64_2;
    openat;
    openat64;
    __openat_2;
    __openat64_2;
    opendir;
    readlink;
    stat;
    stat64;
    __xstat;
    __xstat64;

  local:
    *;
};
